def mode_to_stages(apps, schema_editor):
    """Old single `mode` -> the two stage switches (form -> written, practical -> practical)."""
    Exam = apps.get_model("proctoring", "Exam")
    Exam.objects.filter(mode="practical").update(written_enabled=False, practical_enabled=True)
    Exam.objects.filter(mode="form").update(written_enabled=True, practical_enabled=False)


def stages_to_mode(apps, schema_editor):
    Exam = apps.get_model("proctoring", "Exam")
    Exam.objects.filter(written_enabled=False, practical_enabled=True).update(mode="practical")
    Exam.objects.exclude(written_enabled=False, practical_enabled=True).update(mode="form")


